#!/bin/bash
# Build, install and launch the iOS app on the simulator.
#
# Deliberately NOT xcodebuild: on this machine it deadlocks on Xcode's
# IDEContainer uniquing lock before compiling anything — zero object files
# after 17 minutes, with or without the SwiftPM dependency. swiftc builds the
# same sources in seconds, so the .app bundle is assembled by hand.
# PokePredictor.xcodeproj is still generated by xcodegen for editing in Xcode.
set -euo pipefail
cd "$(dirname "$0")/PokePredictor"

DEVICE="${1:-iPhone 17 Pro Max}"
SDK=$(xcrun --sdk iphonesimulator --show-sdk-path)
APP=build/PokePredictor.app

# The catalogue is generated from the web app's data files every build, so
# the two can never drift.
python3 ../tools/make-resources.py

rm -rf "$APP" && mkdir -p "$APP"
xcrun -sdk iphonesimulator swiftc \
  -target arm64-apple-ios17.0-simulator -sdk "$SDK" \
  -emit-executable -o "$APP/PokePredictor" -parse-as-library -O \
  Sources/*.swift ../PokePredictorKit/Sources/PokePredictorKit/*.swift

cp Resources/cards.json Resources/sets.json "$APP/"
cp Info-template.plist "$APP/Info.plist"

# Codesign refuses a bundle carrying extended attributes.
xattr -cr "$APP"
codesign --force --sign - "$APP"

UDID=$(xcrun simctl list devices available | grep "$DEVICE (" | head -1 | sed -E 's/.*\(([0-9A-F-]{36})\).*/\1/')
xcrun simctl boot "$UDID" 2>/dev/null || true
xcrun simctl install "$UDID" "$APP"
xcrun simctl launch "$UDID" com.simontariq.pokepredictor
